        var j = 0;
        var now_dd = new Date();

        $.each(data.items, function (i, item) {
          // 目的の文書番号でなかったら
          if (-1 == self.ary_doc_no.indexOf(item.disclosureCode)) {
            return true;
          }

          //disclosureItemCode【11321】または【11322】は表示
          var e = 0;
