          var iCodes = '';
          if (item.disclosureItemCodes) {
            $.each(item.disclosureItemCodes, function (e, disclosureItemCode) {
              itemCodes = disclosureItemCode.itemCode;
              iCodes += itemCodes;
              e++;
            });
          }
          var regexp = '11321';
					var regexp2 = '11322';
          var res;
					if (item.disclosureCode == '13') {
						if (((res = iCodes.includes(regexp)) == false) && ((res = iCodes.includes(regexp2)) == false)) {
							return true;
						}
					}

          // 日付設定
          var date = item.publishDate.split(' ')[0].split('/');
          var dateStr = date[0] + '/' + date[1] + '/' + date[2];
          var date_dd = new Date(parseInt(date[0], 10),
            parseInt(date[1], 10) - 1,
            parseInt(date[2], 10));

          // fiscalYearEndがあるときは
          if (item.fiscalYearEnd != null) {
            var fyEnd = item.fiscalYearEnd;
            var fyEndY = fyEnd.substring(0, 4);
            var fyEndQ = fyEnd.substring(4, 8);
            var entry_year = Number(fyEndY);
						if (fyEndQ == '0331') {
              entry_year = Number(fyEndY);
            } else if (fyEndQ == '0630') {
							entry_year = Number(fyEndY) + 1 ;
            } else if (fyEndQ == '0930') {
							entry_year = Number(fyEndY) + 1 ;
            } else if (fyEndQ == '1231') {
							entry_year = Number(fyEndY) + 1 ;
            }
          }
          // fiscalYearEndがないときは
          else {

            // 年度の算出
            var entry_year = self.getFiscalYear(item.title);
            if ("" == entry_year) {
              var date = item.publishDate.split(' ')[0].split('/');
              if (7 <= Number(date[1])) {
                entry_year = Number(date[0]) + 1;
              } else {
                entry_year = Number(date[0]);
              }

            }
          }
          if (('' == self.fdate || !self.fdate)) {
            if (j < 0) {
              return true;
            }
          } else if (self.fdate != entry_year) {
            return true;
          }

          var entrytype = '';
          var url = '';
          var size = '';
          var page = '';

          if (item.files) {
            $.each(item.files, function (j, file) {
              if (file.type == 'PDF-GENERAL') {
                url = file.url;
                size = parseInt(file.size);
                page = file.page;
              } else if (file.type == 'HTML-GENERAL') {
                url = file.url;

              }

            });
          }

          if (size > 0) {
            if (size > 1000 && size < 1000000) {
              size = parseInt(size / 1000) + 'K';
            } else if (size > 1000000) {
              size = parseInt(size / 1000000) + 'M';
            }
          } else {
            size = '－';
          }

          //ページ数の生成
          if (page <= 0) {
            page = '－';
          }

          // 画面表示


          cont += '<li>';

          cont += '<p class="date">' + dateStr + '</p>';
          
          cont += '<div class="date-docs">';

          if (url != '' && size != '－') {
            cont += '<p class="date-title file">';
            cont += '<a href="' + url + '" target="_blank">';
          } else if (url != '') {
            cont += '<p class="date-title">';
            cont += '<a href="' + url + '" target="_blank">';
          } else {
            cont += '<p class="date-title">';
          }

          cont += item.title;
          
          if (url != '') {
            cont += '</a>';
          }

          cont += '</p>';

          if (url != '' && size != '－') {
            cont += '<span class="date-icon">' + size + 'B</span>';
          }

          cont += '</div>';

          cont += '</li>';


          j++;
        });
      }

      if (cont == '') {
        cont += '<li><p>ただいま掲載する事項はございません。</p></li>';        
      }

      $('#xj-mainlist').append(cont);
    });
  }

